"UPDATE lead_work_items SET converted_booking_id=?,status='converted',lifecycle_state='converted',updated_at=? WHERE id=? AND converted_booking_id IS NULL AND lifecycle_state!='dropped'").bind(input.bookingId,now,leadId).run();await recordMarketingConversionFact(db,{eventType:"payment_captured",businessReference:String(payment?.id||input.bookingId),leadId,customerId:input.customerId,bookingId:input.bookingId,paymentId:String(payment?.id||""),valueMinor:Math.max(0,Math.round(Number(payment?.amount||0)*100)),currency:String(payment?.currency||commercial.currency),occurredAt:now}).catch(()=>{});await creditSalesOwner(db,leadId,input.bookingId);return{leadId,converted:true,attribution:"lead"};}await db.prepare("UPDATE lead_work_items SET last_outcome='booking_initiated',initiated_booking_id=?,lifecycle_state=CASE WHEN lifecycle_state IN ('new','contacted') THEN 'qualified' ELSE lifecycle_state END,next_action_at=?,updated_at=? WHERE id=? AND converted_booking_id IS NULL AND lifecycle_state NOT IN ('converted','dropped')").bind(input.bookingId,now,now,leadId).run();await recordMarketingConversionFact(db,{eventType:"lead_qualified",businessReference:leadId,leadId,customerId:input.customerId,occurredAt:now}).catch(()=>{});return{leadId,converted:false,attribution:"lead"};}

