type Db=D1Database;type Row=Record<string,unknown>;const leadWorkItemsEnsured=new WeakSet<Db>();
export async function ensureLeadWorkItemsTable(db:Db){if(leadWorkItemsEnsured.has(db))return;await db.batch([db.prepare("CREATE TABLE IF NOT EXISTS lead_work_items (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, source TEXT NOT NULL, service TEXT NOT NULL, owner TEXT NOT NULL, manager TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', stage TEXT NOT NULL DEFAULT 'day_1', work_day INTEGER NOT NULL DEFAULT 1, assigned_at INTEGER NOT NULL, first_action_due_at INTEGER NOT NULL, manager_alert_at INTEGER NOT NULL, first_action_at INTEGER, call_attempts INTEGER NOT NULL DEFAULT 0, whatsapp_attempts INTEGER NOT NULL DEFAULT 0, last_outcome TEXT, next_action_at INTEGER, recycle_at INTEGER, recycle_cycle INTEGER NOT NULL DEFAULT 0, opt_out INTEGER NOT NULL DEFAULT 0, converted_booking_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)"),db.prepare("CREATE INDEX IF NOT EXISTS idx_lead_work_items_customer ON lead_work_items(customer_id,status,assigned_at)")]);const columns=await db.prepare("PRAGMA table_info(lead_work_items)").all<Row>().catch(()=>({results:[]as Row[]}));if(columns.results.length&&!columns.results.some(column=>String(column.name)==="initiated_booking_id")){await db.prepare("ALTER TABLE lead_work_items ADD COLUMN initiated_booking_id TEXT").run().catch(async error=>{const after=await db.prepare("PRAGMA table_info(lead_work_items)").all<Row>();if(!after.results.some(column=>String(column.name)==="initiated_booking_id"))throw error;});}await ensureLeadLifecycleColumn(db);await db.prepare("CREATE TABLE IF NOT EXISTS booking_attribution (booking_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL,service_code TEXT NOT NULL,attribution_type TEXT NOT NULL,lead_id TEXT,source TEXT NOT NULL DEFAULT 'system',detail_json TEXT NOT NULL DEFAULT '{}',recorded_at INTEGER NOT NULL)").run();await db.prepare("CREATE INDEX IF NOT EXISTS idx_booking_attribution_type ON booking_attribution(attribution_type,recorded_at)").run().catch(()=>{});leadWorkItemsEnsured.add(db);}
export type BookingAttributionType="lead"|"direct_booking";
async function recordAttribution(db:Db,input:{bookingId:string;customerId:string;serviceCode:string;type:BookingAttributionType;leadId?:string|null;detail?:unknown;strict?:boolean}){const insert=db.prepare("INSERT OR IGNORE INTO booking_attribution (booking_id,customer_id,service_code,attribution_type,lead_id,source,detail_json,recorded_at) VALUES (?,?,?,?,?,?,?,?)"+(input.strict?" RETURNING customer_id,service_code,attribution_type,lead_id,detail_json":"")).bind(input.bookingId,input.customerId,input.serviceCode,input.type,input.leadId??null,input.type==="lead"?"lead_work_item":"system_direct_booking",JSON.stringify(input.detail??{}),Date.now());if(!input.strict){await insert.run();return;}const inserted=await insert.first<Row>();const recorded=inserted??await db.prepare("SELECT customer_id,service_code,attribution_type,lead_id,detail_json FROM booking_attribution WHERE booking_id=?").bind(input.bookingId).first<Row>();const wanted=input.detail as {threadId?:string|null}|undefined;const stored=JSON.parse(String(recorded?.detail_json||"{}"));if(!recorded||String(recorded.customer_id)!==input.customerId||normalizeLeadServiceCode(recorded.service_code)!==normalizeLeadServiceCode(input.serviceCode)||String(recorded.attribution_type)!==input.type||String(recorded.lead_id||"")!==String(input.leadId||"")||wanted?.threadId&&stored.threadId&&wanted.threadId!==stored.threadId)throw new Response("Booking attribution changed concurrently",{status:409});}
async function commercials(db:Db,bookingId:string){const booking=await db.prepare("SELECT total_amount,currency FROM canonical_bookings WHERE id=?").bind(bookingId).first<Row>().catch(()=>null);return{valueMinor:Math.max(0,Math.round(Number(booking?.total_amount||0)*100)),currency:String(booking?.currency||"INR")};}
async function latestPayment(db:Db,bookingId:string,capturedOnly=false){const status=capturedOnly?" AND status='captured'":"";try{return await db.prepare(`SELECT id,status,amount,currency FROM booking_payments WHERE booking_id=?${status} ORDER BY updated_at DESC LIMIT 1`).bind(bookingId).first<Row>();}catch{try{return await db.prepare(`SELECT id,status,amount,currency FROM booking_payments WHERE booking_id=?${status} LIMIT 1`).bind(bookingId).first<Row>();}catch{return db.prepare(`SELECT id,status,amount FROM booking_payments WHERE booking_id=?${status} LIMIT 1`).bind(bookingId).first<Row>().catch(()=>null);}}}
async function creditSalesOwner(db:Db,leadId:string,bookingId:string){return attributeConvertedLeadBookingToOwner(db,{leadId,bookingId,actorId:"system:payment-capture"}).catch(()=>({attributed:false,duplicatePrevented:false,conflict:false,reason:"sales_attribution_error"}));}
