/** Validate explicit conversation origin before booking effects. Never infer another lead. */
export async function validateBookingOrigin(db:Db,input:{customerId:string;serviceCode:string;leadId?:string|null;threadId?:string|null;bookingId?:string}){
 await ensureLeadWorkItemsTable(db);
 const service=normalizeLeadServiceCode(input.serviceCode);let leadId=input.leadId?.trim()||null;
 const threadId=input.threadId?.trim()||null;
 if(threadId){
  const thread=await db.prepare("SELECT customer_id,lead_id,booking_id FROM communication_threads WHERE id=?").bind(threadId).first<Row>();
  if(!thread||String(thread.customer_id)!==input.customerId)throw new Response("Booking conversation ownership denied",{status:403});
  if(thread.booking_id&&String(thread.booking_id)!==input.bookingId)throw new Response("Conversation is already bound to another booking",{status:409});
  if(leadId&&String(thread.lead_id||"")!==leadId)throw new Response("Booking lead conflicts with conversation",{status:409});
  leadId=String(thread.lead_id||"").trim()||null;
 }
 if(leadId){
  const lead=await db.prepare("SELECT customer_id,service,initiated_booking_id,converted_booking_id,lifecycle_state FROM lead_work_items WHERE id=?").bind(leadId).first<Row>();
  if(!lead||String(lead.customer_id)!==input.customerId)throw new Response("Booking lead ownership denied",{status:403});
  if(normalizeLeadServiceCode(lead.service)!==service)throw new Response("Booking lead service mismatch",{status:409});
  if([lead.initiated_booking_id,lead.converted_booking_id].some(id=>id&&String(id)!==input.bookingId)||String(lead.lifecycle_state)==="dropped")throw new Response("Lead is unavailable for this booking",{status:409});
 }
 return{leadId,threadId};
}

export async function attributeBookingToOpenLead(db:Db,input:{customerId:string;bookingId:string;leadId?:string|null;threadId?:string|null}):Promise<{leadId:string|null;converted:boolean;attribution:BookingAttributionType}>{
