 if(prior&&(String(prior.customer_id)!==input.customerId||normalizeLeadServiceCode(prior.service_code)!==bookedService||origin.leadId&&String(prior.lead_id||"")!==origin.leadId))throw new Response("Booking attribution conflicts with origin",{status:409});
 if(prior&&origin.threadId){const detail=JSON.parse(String(prior.detail_json||"{}"));if(detail.threadId&&detail.threadId!==origin.threadId)throw new Response("Booking attribution belongs to another conversation",{status:409});}
