 const candidates=explicit?{results:[] as Row[]}:await db.prepare("SELECT id,service FROM lead_work_items WHERE customer_id=? AND converted_booking_id IS NULL AND initiated_booking_id IS NULL AND status NOT IN ('closed','converted') AND lifecycle_state NOT IN ('converted','dropped') ORDER BY assigned_at DESC LIMIT 100").bind(input.customerId).all<Row>();
