async function caseCustomerNotifications(db:Db,asOf:number,actorId:string){const empty={attempted:0,enqueued:0,suppressed:0,duplicatePrevented:0,skipped:0,errors:[] as string[],transport:"canonical_chat_outbox",externalDelivery:false};if(asOf>Date.now())return{...empty,skippedFutureClock:true};try{if(!(await tableExists(db,"unified_cases"))||!(await tableExists(db,"canonical_customers")))return{...empty,unavailable:true};const rows=await db.prepare("SELECT c.id,c.title,c.status,c.customer_id,c.booking_id,c.owner_email,c.first_response_due_at,c.resolution_due_at,c.first_responded_at,cc.city_id FROM unified_cases c JOIN canonical_customers cc ON cc.id=c.customer_id WHERE c.status NOT IN ('resolved','closed') AND c.customer_id IS NOT NULL AND c.booking_id IS NOT NULL AND ((c.first_responded_at IS NULL AND c.first_response_due_at IS NOT NULL AND c.first_response_due_at<=?) OR (c.resolution_due_at IS NOT NULL AND c.resolution_due_at<=?)) ORDER BY c.created_at").bind(asOf,asOf).all<Row>();let attempted=0,enqueued=0,suppressed=0,duplicatePrevented=0,skipped=0;const errors:string[]=[];for(const row of rows.results){const caseId=text(row.id),customerId=text(row.customer_id),bookingId=text(row.booking_id),cityId=text(row.city_id),owner=text(row.owner_email)||undefined;if(!caseId||!customerId||!bookingId||!cityId){skipped++;continue;}const events:Array<{kind:"first_response"|"resolution";templateKey:string;dueAt:number;notice:string}>=[];if(!row.first_responded_at&&row.first_response_due_at!=null&&Number(row.first_response_due_at)<=asOf)events.push({kind:"first_response",templateKey:"case_first_response_overdue",dueAt:Number(row.first_response_due_at),notice:"Your PawSpace support case has crossed its first-response target and is being escalated for staff attention."});if(row.resolution_due_at!=null&&Number(row.resolution_due_at)<=asOf)events.push({kind:"resolution",templateKey:"case_resolution_overdue",dueAt:Number(row.resolution_due_at),notice:"Your PawSpace support case has